-- Banque Téranga (fictive) · monétique · SQL Server
-- À exécuter dans la base teranga_monetique (créée par make demo-data). Rejouable.
SET NOCOUNT ON;
DROP TABLE IF EXISTS dbo.transactions_cartes, dbo.cartes, dbo.gab;
GO
CREATE TABLE dbo.gab (
  id INT PRIMARY KEY, code VARCHAR(12) NOT NULL UNIQUE, emplacement NVARCHAR(60) NOT NULL, ville NVARCHAR(40) NOT NULL, statut NVARCHAR(20) NOT NULL
);
CREATE TABLE dbo.cartes (
  id INT PRIMARY KEY, numero_carte CHAR(16) NOT NULL UNIQUE, numero_client VARCHAR(12) NOT NULL, type_carte NVARCHAR(30) NOT NULL,
  date_expiration DATE NOT NULL, plafond_retrait DECIMAL(14,2) NOT NULL, statut NVARCHAR(10) NOT NULL
);
CREATE TABLE dbo.transactions_cartes (
  id INT PRIMARY KEY, carte_id INT NOT NULL REFERENCES dbo.cartes (id), date_transaction DATETIME2(0) NOT NULL,
  commercant NVARCHAR(60) NOT NULL, ville NVARCHAR(40) NOT NULL, montant DECIMAL(14,2) NOT NULL, devise CHAR(3) NOT NULL,
  statut NVARCHAR(10) NOT NULL, gab_id INT NULL REFERENCES dbo.gab (id)
);
CREATE INDEX ix_tx_date ON dbo.transactions_cartes (date_transaction);
GO
GO
